    ok('rental paperwork stays on the list once answered, even if payment changes', pg.is_visible('#sec-rental'))
    pg.click('button[data-id="stock"][data-v="no"]'); dlg = []; pg.once('dialog', lambda x: (dlg.append(x.message), x.dismiss()))
    pg.click('.topbar .back'); pg.wait_for_timeout(300); ok('leaving with a Not done lacking why/date warns (and Cancel stays)', dlg and 'Not done' in dlg[0] and 'install-requirements' in pg.url)
    pg.click('button[data-id="stock"][data-v="yes"]')
    for i in ['mat', 'video', 'photos', 'i-labor']: pg.click(f'button[data-id="{i}"][data-v="yes"]')
