    api('POST', '/api/reset', {}); pg.goto(URL); pg.reload(); pg.wait_for_timeout(800); pg.click('button[data-id="stock"][data-v="no"]')
    pg.select_option('#why-stock select', index=1); pg.evaluate("document.querySelector('#why-stock input[type=date]').value='2020-01-01';document.querySelector('#why-stock input[type=date]').dispatchEvent(new Event('change'))"); pg.wait_for_timeout(200)
    ok('a past "by when" date is cleared (Submit stays blocked)', pg.input_value('#why-stock input[type=date]') == '' and pg.is_disabled('#submitBtn'))
    pg.click('#parkBtn'); pg.select_option('#parkReason', index=1); pg.fill('#parkDate', '2020-01-01'); pg.click('#parkSave'); pg.wait_for_timeout(300)
    ok('past wrap-up date refused, modal stays open', 'passed' in pg.inner_text('#parkMsg') and pg.locator('#parkModal.on').count() == 1)
