    p3.close(run_before_unload=True); pg.wait_for_timeout(300); ok('empty form: closing the tab does not warn', not kinds)
    p4 = ctx.new_page(); p4.goto(URL); p4.reload(); p4.wait_for_timeout(700); kinds2 = []; p4.on('dialog', lambda x: (kinds2.append(x.type), x.accept()))
    p4.select_option('#pay', index=1); p4.click('button[data-id="stock"][data-v="yes"]'); p4.close(run_before_unload=True); pg.wait_for_timeout(400)
