    ok('there is no Electrical card (disconnect, service outlet and electrical labor are gone)', pg.locator('#sec-elec').count() == 0 and pg.locator('button[data-id="e-labor"]').count() == 0 and pg.locator('button[data-id="e-outlet"]').count() == 0 and pg.locator('button[data-id="e-disconnect"]').count() == 0)
    ok('there is no Heads-up for Install card; Filter size sits under Vendor in the equipment section', pg.locator('#sec-email').count() == 0 and pg.is_visible('#row-stock #filterTxt') and pg.is_visible('#row-stock #vendorTxt'))
